//<fix start>
    @Test
    public void testLogicDeleteSql() throws Exception {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);

        // Parse the XML-like string to handle non-deterministic field order
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        InputSource is = new InputSource(new StringReader(whereAllIfColumns));
        Document doc = builder.parse(is);

        Element whereElement = doc.getDocumentElement();
        NodeList children = whereElement.getChildNodes();

        Set<String> actualIfTags = new HashSet<>();
        StringBuilder trailingText = new StringBuilder();

        for (int i = 0; i < children.getLength(); i++) {
            Node node = children.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE && "if".equals(node.getNodeName())) {
                Element ifElement = (Element) node;
                String testAttr = ifElement.getAttribute("test");
                String textContent = ifElement.getTextContent();
                actualIfTags.add("<if test=\"" + testAttr + "\">" + textContent + "</if>");
            } else if (node.getNodeType() == Node.TEXT_NODE) {
                trailingText.append(node.getTextContent());
            }
        }

        Set<String> expectedIfTags = new HashSet<>();
        expectedIfTags.add("<if test=\"id != null\"> AND id = #{id}</if>");
        expectedIfTags.add("<if test=\"username != null\"> AND username = #{username}</if>");

        Assert.assertEquals(expectedIfTags, actualIfTags);
        Assert.assertEquals(" AND is_valid = 1", trailingText.toString());

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Assert.assertEquals("<set>username = #{username},is_valid = 1,</set>", updateSetColumns);
    }
