  @Test
  public void testAssembleLongPollRefreshUrlWithMultipleNamespaces() throws Exception {
    String someUri = someServerUrl;
    String someAppId = "someAppId";
    String someCluster = "someCluster+ &.-_someSign";
    String someNamespace = "someName";
    String anotherNamespace = "anotherName";
    long someNotificationId = 1;
    long anotherNotificationId = 2;
    Map<String, Long> notificationsMap =
        ImmutableMap.of(someNamespace, someNotificationId, anotherNamespace, anotherNotificationId);

    String longPollRefreshUrl =
        remoteConfigLongPollService
            .assembleLongPollRefreshUrl(someUri, someAppId, someCluster, null, notificationsMap);

    assertTrue(longPollRefreshUrl.contains(someServerUrl + "/notifications/v2?"));
    assertTrue(longPollRefreshUrl.contains("appId=" + someAppId));
    assertTrue(longPollRefreshUrl.contains("cluster=someCluster%2B+%26.-_someSign"));

    // Extract notifications query parameter
    String notificationsKey = "notifications=";
    int startIndex = longPollRefreshUrl.indexOf(notificationsKey);
    assertTrue(startIndex != -1);
    String encodedNotifications = longPollRefreshUrl.substring(startIndex + notificationsKey.length());
    // Remove any trailing query parameters
    int ampIndex = encodedNotifications.indexOf("&");
    if (ampIndex != -1) {
      encodedNotifications = encodedNotifications.substring(0, ampIndex);
    }

    String decodedNotifications = URLDecoder.decode(encodedNotifications, "UTF-8");

    // Parse JSON and verify content order-insensitively
    Gson gson = new Gson();
    Type type = new TypeToken<List<JsonObject>>() {}.getType();
    List<JsonObject> actualNotifications = gson.fromJson(decodedNotifications, type);

    Set<JsonObject> expectedNotifications = new HashSet<>();
    JsonObject n1 = new JsonObject();
    n1.addProperty("namespaceName", someNamespace);
    n1.addProperty("notificationId", someNotificationId);
    expectedNotifications.add(n1);

    JsonObject n2 = new JsonObject();
    n2.addProperty("namespaceName", anotherNamespace);
    n2.addProperty("notificationId", anotherNotificationId);
    expectedNotifications.add(n2);

    assertEquals(2, actualNotifications.size());
    assertEquals(expectedNotifications, new HashSet<>(actualNotifications));
  }
