	public void checkMerge_1() throws Exception {
		Map<String, ?> merged = Maps.merge(
			Stream.of(getClass().getField("one").getAnnotations()).collect(Collectors.toList()));

		// Sort lists within the map to ensure deterministic comparison regardless of annotation processing order
		Map<String, Object> sortedMerged = new HashMap<>();
		merged.forEach((k, v) -> {
			if (v instanceof List) {
				List<Object> list = new ArrayList<>((List<?>) v);
				Collections.sort(list, (o1, o2) -> ((Comparable) o1).compareTo(o2));
				sortedMerged.put(k, list);
			} else {
				sortedMerged.put(k, v);
			}
		});

		Assert.assertEquals(
			Maps.of(
				"a", Arrays.asList("bar", "baz", "foo"),
				"b", Arrays.asList(1, 1, 1, 2, 2),
				"c", true,
				"cpt3", true),
			sortedMerged);
