  @Test
  public void testAssembleLongPollRefreshUrl() throws Exception {
    String someUri = someServerUrl;
    String someAppId = "someAppId";
    String someCluster = "someCluster+ &.-_someSign";
    String someNamespace = "someName";
    long someNotificationId = 1;
    Map<String, Long> notificationsMap = ImmutableMap.of(someNamespace, someNotificationId);

    String longPollRefreshUrl =
        remoteConfigLongPollService
            .assembleLongPollRefreshUrl(someUri, someAppId, someCluster, null, notificationsMap);

    assertTrue(longPollRefreshUrl.contains(someServerUrl + "/notifications/v2?"));
    assertTrue(longPollRefreshUrl.contains("appId=" + someAppId));
    assertTrue(longPollRefreshUrl.contains("cluster=someCluster%2B+%26.-_someSign"));

    // Parse the notifications parameter to verify content regardless of JSON key order
    String query = longPollRefreshUrl.substring(longPollRefreshUrl.indexOf("?") + 1);
    Map<String, String> params = Splitter.on('&').withKeyValueSeparator('=').split(query);
    String notificationsParam = params.get("notifications");
    assertNotNull(notificationsParam);

    String decodedNotifications = URLDecoder.decode(notificationsParam, "UTF-8");

    Gson gson = new Gson();
    JsonArray notificationsArray = gson.fromJson(decodedNotifications, JsonArray.class);
    assertEquals(1, notificationsArray.size());

    JsonObject notificationObj = notificationsArray.get(0).getAsJsonObject();
    assertEquals(someNamespace, notificationObj.get("namespaceName").getAsString());
    assertEquals(someNotificationId, notificationObj.get("notificationId").getAsLong());
  }
//<fix end>

