    @Test
    public void noArray() {
        final WithArrays wa = new WithArrays();
        final String actual = toString(wa);

        // Validate prefix and suffix to ensure structure is correct
        final String prefix = getClassPrefix(wa) + "[" + BR;
        final String suffix = BR + "]";
        assertTrue(actual.startsWith(prefix), "String should start with class prefix and opening bracket");
        assertTrue(actual.endsWith(suffix), "String should end with closing bracket");

        // Extract content lines
        final String content = actual.substring(prefix.length(), actual.length() - suffix.length());
        final String[] lines = content.split(BR);

        // Normalize lines into a Set to handle non-deterministic field order
        final Set<String> actualFields = new HashSet<>();
        for (String line : lines) {
            String normalized = line.trim();
            // Remove trailing comma which depends on field order (last field has no comma)
            if (normalized.endsWith(",")) {
                normalized = normalized.substring(0, normalized.length() - 1);
            }
            actualFields.add(normalized);
        }

        // Define expected fields independently of order
        final Set<String> expectedFields = new HashSet<>();
        expectedFields.add("boolArray=<null>");
        expectedFields.add("charArray=<null>");
        expectedFields.add("intArray=<null>");
        expectedFields.add("doubleArray=<null>");
        expectedFields.add("longArray=<null>");
        expectedFields.add("stringArray=<null>");

        assertEquals(expectedFields, actualFields);
    }
