//<fix start>
    @Test
    public void testReflectionHierarchyHashCode() {
        // These assertions are deterministic because all field values are 0.
        // The calculation (initial * multiplier^N) depends only on the number of fields (N),
        // not their order.
        assertEquals(17 * 37 * 37, HashCodeBuilder.reflectionHashCode(new TestSubObject(0, 0, 0)));
        assertEquals(17 * 37 * 37 * 37, HashCodeBuilder.reflectionHashCode(new TestSubObject(0, 0, 0), true));

        // Non-deterministic cases: The hash code depends on the iteration order of fields
        // returned by reflection (getDeclaredFields), which is not guaranteed.
        // We verify that the result matches one of the valid permutations of field orders.

        int valA = 123456;
        int valB = 7890;
        int valC = 0; // Value for the parent class field

        // Case: No hierarchy (TestSubObject has 2 fields: valA, valB)
        int actualNoHierarchy = HashCodeBuilder.reflectionHashCode(new TestSubObject(valA, valB, valC));
        int expectedNoHierarchy1 = new HashCodeBuilder().append(valA).append(valB).toHashCode();
        int expectedNoHierarchy2 = new HashCodeBuilder().append(valB).append(valA).toHashCode();
        assertTrue(actualNoHierarchy == expectedNoHierarchy1 || actualNoHierarchy == expectedNoHierarchy2,
                "HashCode mismatch for non-hierarchy case. Actual: " + actualNoHierarchy);

        // Case: Hierarchy (TestSubObject has 2 fields + 1 parent field: valA, valB, valC)
        int actualHierarchy = HashCodeBuilder.reflectionHashCode(new TestSubObject(valA, valB, valC), true);
        Set<Integer> expectedHierarchy = new HashSet<>();
        // Add all 6 permutations of 3 fields
        expectedHierarchy.add(new HashCodeBuilder().append(valA).append(valB).append(valC).toHashCode());
        expectedHierarchy.add(new HashCodeBuilder().append(valA).append(valC).append(valB).toHashCode());
        expectedHierarchy.add(new HashCodeBuilder().append(valB).append(valA).append(valC).toHashCode());
        expectedHierarchy.add(new HashCodeBuilder().append(valB).append(valC).append(valA).toHashCode());
        expectedHierarchy.add(new HashCodeBuilder().append(valC).append(valA).append(valB).toHashCode());
        expectedHierarchy.add(new HashCodeBuilder().append(valC).append(valB).append(valA).toHashCode());

        assertTrue(expectedHierarchy.contains(actualHierarchy),
                "HashCode mismatch for hierarchy case. Actual: " + actualHierarchy);
    }
