        assertEquals(17 * 37 * 37, HashCodeBuilder.reflectionHashCode(new TestSubObject(0, 0, 0)));
        assertEquals(17 * 37 * 37 * 37, HashCodeBuilder.reflectionHashCode(new TestSubObject(0, 0, 0), true));

        // Test with non-zero values. The order of fields returned by reflection is non-deterministic,
        // so the hash code can be one of the valid permutations of the field values.
        // TestSubObject(123456, 7890, 0) appears to have 2 relevant fields for non-hierarchy hash code.
        // The values involved are 7890 and 123456.
        int valA = 7890;
        int valB = 123456;
        int actualNonHierarchy = HashCodeBuilder.reflectionHashCode(new TestSubObject(123456, 7890, 0));
        assertTrue(actualNonHierarchy == (17 * 37 + valA) * 37 + valB || 
                   actualNonHierarchy == (17 * 37 + valB) * 37 + valA,
                   "HashCode should match one of the valid field order permutations");

        // Test with hierarchy (true). Appears to involve 3 fields.
        // The values involved are 7890, 0, and 123456.
        int v1 = 7890;
        int v2 = 0;
        int v3 = 123456;
        java.util.Set<Integer> validHashCodes = new java.util.HashSet<>();
        // Generate all 6 permutations of 3 values
        validHashCodes.add(((17 * 37 + v1) * 37 + v2) * 37 + v3);
        validHashCodes.add(((17 * 37 + v1) * 37 + v3) * 37 + v2);
        validHashCodes.add(((17 * 37 + v2) * 37 + v1) * 37 + v3);
        validHashCodes.add(((17 * 37 + v2) * 37 + v3) * 37 + v1);
        validHashCodes.add(((17 * 37 + v3) * 37 + v1) * 37 + v2);
        validHashCodes.add(((17 * 37 + v3) * 37 + v2) * 37 + v1);

        int actualHierarchy = HashCodeBuilder.reflectionHashCode(new TestSubObject(123456, 7890, 0), true);
        assertTrue(validHashCodes.contains(actualHierarchy), 
                   "HashCode with hierarchy should match one of the valid field order permutations");
    }
