    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String result = toString(wa);

        // Parse the result string into a list of field strings to handle non-deterministic field order
        final List<String> actualFields = new ArrayList<>();
        StringBuilder currentField = new StringBuilder();

        for (String line : result.split(BR)) {
            // Skip the header line (class name + hash) and the footer line (bracket)
            if (line.startsWith(getClassPrefix(wa)) || line.equals("]")) {
                continue;
            }

            // A line starts a new field if it has indentation of 2 spaces and contains an '='
            // This distinguishes field lines (e.g., "  doubleArray={") from content lines (e.g., "    1.0,") or closing braces (e.g., "  },")
            if (line.startsWith("  ") && !line.startsWith("    ") && line.contains("=")) {
                if (currentField.length() > 0) {
                    actualFields.add(currentField.toString());
                }
                currentField = new StringBuilder(line);
            } else if (currentField.length() > 0) {
                // Append content lines (array elements, closing braces) to the current field
                currentField.append(BR).append(line);
            }
        }
        // Add the last field found
        if (currentField.length() > 0) {
            actualFields.add(currentField.toString());
        }

        // Normalize fields: remove trailing comma if present, as it depends on field order
        final List<String> normalizedActualFields = new ArrayList<>();
        for (String field : actualFields) {
            if (field.endsWith(",")) {
                normalizedActualFields.add(field.substring(0, field.length() - 1));
            } else {
                normalizedActualFields.add(field);
            }
        }
        normalizedActualFields.sort(null);

        // Construct the expected list of fields (order independent)
        final List<String> expectedFields = new ArrayList<>();
        expectedFields.add("  boolArray=<null>");
        expectedFields.add("  charArray=<null>");
        expectedFields.add("  intArray=<null>");
        expectedFields.add("  doubleArray={" + BR + "    1.0," + BR + "    2.0" + BR + "  }");
        expectedFields.add("  longArray=<null>");
        expectedFields.add("  stringArray=<null>");
        expectedFields.sort(null);

        assertEquals(expectedFields, normalizedActualFields);
    }
