                    if (val.endsWith(",")) {
                        val = val.substring(0, val.length() - 1);
                    }
                    actualFields.put(currentField, val);
                }

                // Parse new field
                int eqIdx = line.indexOf('=');
                currentField = line.substring(2, eqIdx);
                currentValue = new StringBuilder();
                currentValue.append(line.substring(eqIdx + 1));
            } else if (currentField != null) {
                // Append continuation lines (e.g., array elements)
                currentValue.append(BR).append(line);
            }
        }

        // Save the last field
        if (currentField != null) {
            String val = currentValue.toString();
            if (val.endsWith(",")) {
                val = val.substring(0, val.length() - 1);
            }
            actualFields.put(currentField, val);
