        Assert.assertTrue(sql.contains("<if test=\"id != null\"> AND id = #{id}</if>"));
        Assert.assertTrue(sql.contains("<if test=\"userName != null\"> AND user_name = #{userName}</if>"));
        Assert.assertTrue(sql.contains("<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>"));
        Assert.assertTrue(sql.contains("<if test=\"state != null\"> AND state = #{state}</if>"));

        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();

        // Find mappings by property name to handle non-deterministic order
        ResultMapping idMapping = null;
        ResultMapping userNameMapping = null;
        ResultMapping addressMapping = null;
        ResultMapping stateMapping = null;

        for (ResultMapping rm : resultMappings) {
            String prop = rm.getProperty();
            if ("id".equals(prop)) {
                idMapping = rm;
            } else if ("userName".equals(prop)) {
                userNameMapping = rm;
            } else if ("address".equals(prop)) {
                addressMapping = rm;
            } else if ("state".equals(prop)) {
                stateMapping = rm;
            }
        }

