    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        // Verify SQL structure order-insensitively to fix ID flakiness
        // 1. Verify SELECT columns
        int fromIndex = sql.indexOf(" FROM user ");
        Assert.assertTrue("SQL should contain ' FROM user '", fromIndex > 0);
        String selectPart = sql.substring("SELECT ".length(), fromIndex);
        Set<String> actualColumns = new HashSet<>();
        for (String col : selectPart.split(",")) {
            actualColumns.add(col.trim());
        }
        Set<String> expectedColumns = new HashSet<>(Arrays.asList("id", "user_name", "address", "state"));
        Assert.assertEquals("SELECT columns mismatch", expectedColumns, actualColumns);

        // 2. Verify WHERE conditions
        Assert.assertTrue("SQL should contain <where>", sql.contains("<where>"));
        Assert.assertTrue("SQL should end with </where>", sql.endsWith("</where>"));
        String wherePart = sql.substring(sql.indexOf("<where>"));

        Set<String> actualConditions = new HashSet<>();
        Pattern pattern = Pattern.compile("<if.*?</if>");
        Matcher matcher = pattern.matcher(wherePart);
        while (matcher.find()) {
            actualConditions.add(matcher.group());
        }

        Set<String> expectedConditions = new HashSet<>(Arrays.asList(
            "<if test=\"id != null\"> AND id = #{id}</if>",
            "<if test=\"userName != null\"> AND user_name = #{userName}</if>",
            "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>",
            "<if test=\"state != null\"> AND state = #{state}</if>"
        ));
        Assert.assertEquals("WHERE conditions mismatch", expectedConditions, actualConditions);

        // Verify ResultMap order-insensitively to fix ID flakiness
        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();

        Map<String, ResultMapping> mappingMap = new HashMap<>();
        for (ResultMapping rm : resultMappings) {
            mappingMap.put(rm.getProperty(), rm);
        }

        // ID Mapping
        Assert.assertTrue("ResultMap should contain 'id' property", mappingMap.containsKey("id"));
        ResultMapping idMapping = mappingMap.get("id");
        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        // UserName Mapping
        Assert.assertTrue("ResultMap should contain 'userName' property", mappingMap.containsKey("userName"));
        ResultMapping userNameMapping = mappingMap.get("userName");
        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());

        // Address Mapping
        Assert.assertTrue("ResultMap should contain 'address' property", mappingMap.containsKey("address"));
        ResultMapping addressMapping = mappingMap.get("address");
        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        // State Mapping
        Assert.assertTrue("ResultMap should contain 'state' property", mappingMap.containsKey("state"));
        ResultMapping stateMapping = mappingMap.get("state");
        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());
    }
