    @Test
    public void testReflectionHashCodeExcludeFields() {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);

        // Hash codes for all permutations of values {1, 2, 3} (order depends on JVM field ordering)
        assertTrue(Arrays.asList(862547, 862583, 863879, 863915, 864281, 864317).contains(HashCodeBuilder.reflectionHashCode(x)));

        assertTrue(Arrays.asList(862547, 862583, 863879, 863915, 864281, 864317).contains(HashCodeBuilder.reflectionHashCode(x, (String[]) null)));
        assertTrue(Arrays.asList(862547, 862583, 863879, 863915, 864281, 864317).contains(HashCodeBuilder.reflectionHashCode(x)));
        assertTrue(Arrays.asList(862547, 862583, 863879, 863915, 864281, 864317).contains(HashCodeBuilder.reflectionHashCode(x, "xxx")));

        // Hash codes for all permutations of values {1, 3} (excluding "two")
        assertTrue(Arrays.asList(23313, 23385).contains(HashCodeBuilder.reflectionHashCode(x, "two")));

