    @Test
    public void testReflectionStatics() {
        final ReflectionStaticFieldsFixture instance1 = new ReflectionStaticFieldsFixture();

        // Helper function to normalize the string output by sorting the fields within the brackets.
        // This ensures the test is robust against non-deterministic field ordering from reflection.
        java.util.function.Function<String, String> normalize = s -> {
            int start = s.indexOf('[');
            int end = s.lastIndexOf(']');
            if (start == -1 || end == -1) {
                return s;
            }
            String[] fields = s.substring(start + 1, end).split(",");
            java.util.Arrays.sort(fields);
            return s.substring(0, start + 1) + String.join(",", fields) + s.substring(end);
        };

        final String expected1 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,instanceString=instanceString,instanceInt=67890]";
        final String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, ReflectionStaticFieldsFixture.class);
        assertEquals(normalize.apply(expected1), normalize.apply(actual1));

        final String expected2 = this.toBaseString(instance1) + "[staticString=staticString,staticInt=12345,staticTransientString=staticTransientString,staticTransientInt=54321,instanceString=instanceString,instanceInt=67890,transientString=transientString,transientInt=98765]";
        final String actual2 = ReflectionToStringBuilder.toString(instance1, null, true, true, ReflectionStaticFieldsFixture.class);
        assertEquals(normalize.apply(expected2), normalize.apply(actual2));

        final String actual3 = this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class);
        assertEquals(normalize.apply(expected1), normalize.apply(actual3));

        final String actual4 = this.toStringWithStatics(instance1, null, ReflectionStaticFieldsFixture.class);
        assertEquals(normalize.apply(expected1), normalize.apply(actual4));
    }
