    @Test
    public void testReflectionHashCodeExcludeFields() throws IllegalAccessException {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);
        java.lang.reflect.Field[] fields = x.getClass().getDeclaredFields();
        java.lang.reflect.AccessibleObject.setAccessible(fields, true);

        java.util.function.Function<String[], Integer> expectedHash = (excludes) -> {
            try {
                HashCodeBuilder b = new HashCodeBuilder();
                java.util.Set<String> excludeSet = excludes == null ? java.util.Collections.emptySet() : new java.util.HashSet<>(java.util.Arrays.asList(excludes));
                for (java.lang.reflect.Field f : fields) {
                    if (!java.lang.reflect.Modifier.isStatic(f.getModifiers()) && !java.lang.reflect.Modifier.isTransient(f.getModifiers()) && !excludeSet.contains(f.getName())) {
                        b.append(f.get(x));
                    }
                }
                return b.toHashCode();
            } catch (java.lang.IllegalAccessException e) {
                throw new RuntimeException(e);
            }
        };

        assertEquals(expectedHash.apply(new String[]{}), HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expectedHash.apply(null), HashCodeBuilder.reflectionHashCode(x, (String[]) null));
        assertEquals(expectedHash.apply(new String[]{}), HashCodeBuilder.reflectionHashCode(x));
        assertEquals(expectedHash.apply(new String[]{"xxx"}), HashCodeBuilder.reflectionHashCode(x, "xxx"));

        assertEquals(expectedHash.apply(new String[]{"two"}), HashCodeBuilder.reflectionHashCode(x, "two"));
        assertEquals(expectedHash.apply(new String[]{"three"}), HashCodeBuilder.reflectionHashCode(x, "three"));

        assertEquals(expectedHash.apply(new String[]{"two", "three"}), HashCodeBuilder.reflectionHashCode(x, "two", "three"));

        assertEquals(expectedHash.apply(new String[]{"one", "two", "three"}), HashCodeBuilder.reflectionHashCode(x, "one", "two", "three"));
        assertEquals(expectedHash.apply(new String[]{"one", "two", "three", "xxx"}), HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx"));
    }
