//<fix start>
    @Test
    public void testReflectionHierarchyArrayList() {
        // LANG-1337 without this, the generated string can differ depending on the JVM version/vendor
        final List<Object> list = new ArrayList<>(ARRAYLIST_INITIAL_CAPACITY);
        final String baseString = this.toBaseString(list);
        final String expectedWithTransients = baseString + "[elementData={<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>,<null>},size=0,modCount=0]";
        final String toStringWithTransients = ToStringBuilder.reflectionToString(list, null, true);

        // Parse fields into a Set to handle non-deterministic field order
        java.util.function.Function<String, java.util.Set<String>> parser = str -> {
            java.util.Set<String> fields = new java.util.HashSet<>();
            int startIdx = str.indexOf('[');
            int endIdx = str.lastIndexOf(']');
            if (startIdx != -1 && endIdx != -1 && startIdx < endIdx) {
                String content = str.substring(startIdx + 1, endIdx);
                int depth = 0;
                int lastSplit = 0;
                for (int i = 0; i < content.length(); i++) {
                    char c = content.charAt(i);
                    if (c == '{' || c == '[') {
                        depth++;
                    } else if (c == '}' || c == ']') {
                        depth--;
                    } else if (c == ',' && depth == 0) {
                        fields.add(content.substring(lastSplit, i));
                        lastSplit = i + 1;
                    }
                }
                if (lastSplit < content.length()) {
                    fields.add(content.substring(lastSplit));
                }
            }
            return fields;
        };

        assertTrue(toStringWithTransients.startsWith(baseString + "["), "Prefix mismatch");
        assertEquals(parser.apply(expectedWithTransients), parser.apply(toStringWithTransients), "Fields mismatch with transients");

        final String expectedWithoutTransients = baseString + "[size=0]";
        final String toStringWithoutTransients = ToStringBuilder.reflectionToString(list, null, false);

        assertTrue(toStringWithoutTransients.startsWith(baseString + "["), "Prefix mismatch");
        assertEquals(parser.apply(expectedWithoutTransients), parser.apply(toStringWithoutTransients), "Fields mismatch without transients");
    }
