    public void testReflectionHierarchy() {
        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
        String baseString = this.toBaseString(baseA);

        // Helper to verify fields independent of iteration order
        class Verifier {
            void check(String result, String base, String... expectedFields) {
                assertTrue(result.startsWith(base + "["), "Prefix mismatch: " + result);
                assertTrue(result.endsWith("]"), "Suffix mismatch: " + result);
                String content = result.substring(result.indexOf('[') + 1, result.length() - 1);
                Set<String> actualFields = new HashSet<>(Arrays.asList(content.split(",")));
                Set<String> expectedSet = new HashSet<>(Arrays.asList(expectedFields));
                assertEquals(expectedSet, actualFields, "Field mismatch");
            }
        }
        Verifier v = new Verifier();

        assertEquals(baseString + "[a=a]", ToStringBuilder.reflectionToString(baseA));
        assertEquals(baseString + "[a=a]", ToStringBuilder.reflectionToString(baseA, null));
        assertEquals(baseString + "[a=a]", ToStringBuilder.reflectionToString(baseA, null, false));
        v.check(ToStringBuilder.reflectionToString(baseA, null, true), baseString, "a=a", "transientA=t");
        assertEquals(baseString + "[a=a]", ToStringBuilder.reflectionToString(baseA, null, false, null));
        assertEquals(baseString + "[a=a]", ToStringBuilder.reflectionToString(baseA, null, false, Object.class));
        assertEquals(baseString + "[a=a]", ToStringBuilder.reflectionToString(baseA, null, false, ReflectionTestFixtureA.class));

        final ReflectionTestFixtureB baseB = new ReflectionTestFixtureB();
        baseString = this.toBaseString(baseB);

        v.check(ToStringBuilder.reflectionToString(baseB), baseString, "b=b", "a=a");
        v.check(ToStringBuilder.reflectionToString(baseB), baseString, "b=b", "a=a");
        v.check(ToStringBuilder.reflectionToString(baseB, null), baseString, "b=b", "a=a");
        v.check(ToStringBuilder.reflectionToString(baseB, null, false), baseString, "b=b", "a=a");
        v.check(ToStringBuilder.reflectionToString(baseB, null, true), baseString, "b=b", "transientB=t", "a=a", "transientA=t");
