//<fix start>
    @Test
    public void testReflectionHierarchy() {
        // Normalizer to handle non-deterministic field order from reflection
        Function<String, String> normalizer = s -> {
            int start = s.indexOf('[');
            int end = s.indexOf(']');
            String content = s.substring(start + 1, end);
            String[] parts = content.split(",");
            Arrays.sort(parts);
            return s.substring(0, start + 1) + String.join(",", parts) + "]";
        };

        final ReflectionTestFixtureA baseA = new ReflectionTestFixtureA();
        String baseString = this.toBaseString(baseA);
        assertEquals(normalizer.apply(baseString + "[a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseA)));
        assertEquals(normalizer.apply(baseString + "[a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseA, null)));
        assertEquals(normalizer.apply(baseString + "[a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseA, null, false)));
        assertEquals(normalizer.apply(baseString + "[a=a,transientA=t]"), normalizer.apply(ToStringBuilder.reflectionToString(baseA, null, true)));
        assertEquals(normalizer.apply(baseString + "[a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseA, null, false, null)));
        assertEquals(normalizer.apply(baseString + "[a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseA, null, false, Object.class)));
        assertEquals(normalizer.apply(baseString + "[a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseA, null, false, ReflectionTestFixtureA.class)));

        final ReflectionTestFixtureB baseB = new ReflectionTestFixtureB();
        baseString = this.toBaseString(baseB);
        assertEquals(normalizer.apply(baseString + "[b=b,a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB)));
        assertEquals(normalizer.apply(baseString + "[b=b,a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB)));
        assertEquals(normalizer.apply(baseString + "[b=b,a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB, null)));
        assertEquals(normalizer.apply(baseString + "[b=b,a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB, null, false)));
        assertEquals(normalizer.apply(baseString + "[b=b,transientB=t,a=a,transientA=t]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB, null, true)));
        assertEquals(normalizer.apply(baseString + "[b=b,a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB, null, false, null)));
        assertEquals(normalizer.apply(baseString + "[b=b,a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB, null, false, Object.class)));
        assertEquals(normalizer.apply(baseString + "[b=b,a=a]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB, null, false, ReflectionTestFixtureA.class)));
        assertEquals(normalizer.apply(baseString + "[b=b]"), normalizer.apply(ToStringBuilder.reflectionToString(baseB, null, false, ReflectionTestFixtureB.class)));
    }
