    @Test
    public void shouldJsonSerialiseAndDeserialise() throws IOException {
        // Given
        final Object[] controlData = {1, new CustomObj(), 3};
        final IsIn filter = new IsIn(Arrays.asList(controlData));

        // When
        final String json = JsonSerialiser.serialise(filter);

        // Then
        // Parse JSON to allow order-insensitive comparison of the 'values' array
        final ObjectMapper mapper = new ObjectMapper();
        final JsonNode actualJson = mapper.readTree(json);
        final JsonNode expectedJson = mapper.readTree(String.format("{%n" +
                "  \"class\" : \"uk.gov.gchq.koryphe.impl.predicate.IsIn\",%n" +
                "  \"values\" : [ 1, {\"uk.gov.gchq.koryphe.util.CustomObj\":{\"value\":\"1\"}}, 3 ]%n" +
                "}"));

        // Verify structure completeness and content
        assertThat(actualJson.size()).isEqualTo(expectedJson.size());
        assertThat(actualJson.get("class")).isEqualTo(expectedJson.get("class"));

        // Verify values array content ignoring order
        assertThat(Sets.newHashSet(actualJson.get("values")))
                .containsExactlyElementsOf(Sets.newHashSet(expectedJson.get("values")));

        // When 2
        final IsIn deserialisedFilter = JsonSerialiser.deserialise(json, IsIn.class);

        // Then 2
        assertThat(deserialisedFilter).isNotNull();
        assertThat(deserialisedFilter.getAllowedValues()).containsExactlyElementsOf(Sets.newHashSet(controlData));
    }
