//<fix start>
    @Test
    public void stringArray() {
        final WithArrays wa = new WithArrays();
        wa.stringArray = new String[] { "a", "A" };
        final String actual = toString(wa);

        final String prefix = getClassPrefix(wa) + "[" + BR;
        assertTrue(actual.startsWith(prefix), "String should start with class prefix and opening bracket");
        assertTrue(actual.endsWith("]"), "String should end with closing bracket");

        // Extract content between prefix and final ']'
        String content = actual.substring(prefix.length(), actual.length() - 1);

        // Parse fields into a Set to handle non-deterministic field order
        Set<String> actualFields = new HashSet<>();
        String[] lines = content.split(BR);
        StringBuilder currentField = new StringBuilder();

        for (String line : lines) {
            // Check if line starts a new field: "  fieldName="
            // We check for indentation (2 spaces), a valid Java identifier start char, and an assignment.
            if (line.startsWith("  ") && line.length() > 2 && Character.isJavaIdentifierStart(line.charAt(2)) && line.contains("=")) {
                if (currentField.length() > 0) {
                    String fieldStr = currentField.toString();
                    // Remove trailing comma from the field block for normalization
                    actualFields.add(fieldStr.endsWith(",") ? fieldStr.substring(0, fieldStr.length() - 1) : fieldStr);
                }
                currentField = new StringBuilder(line);
            } else {
                if (currentField.length() > 0) {
                    currentField.append(BR).append(line);
                } else {
                    // Handle case where content might start without a field line (unlikely here)
                    currentField.append(line);
                }
            }
        }
        // Add the last field
        if (currentField.length() > 0) {
            String fieldStr = currentField.toString();
            actualFields.add(fieldStr.endsWith(",") ? fieldStr.substring(0, fieldStr.length() - 1) : fieldStr);
        }

        // Define expected fields in a Set
        Set<String> expectedFields = new HashSet<>();
        expectedFields.add("  boolArray=<null>");
        expectedFields.add("  charArray=<null>");
        expectedFields.add("  intArray=<null>");
        expectedFields.add("  doubleArray=<null>");
        expectedFields.add("  longArray=<null>");
        expectedFields.add("  stringArray={" + BR + "    a," + BR + "    A" + BR + "  }");

        assertEquals(expectedFields, actualFields);
    }
//<fix end>

